<script setup lang="ts">
import{computed,ref}from'vue';import{onPullDownRefresh,onShow}from'@dcloudio/uni-app';import WareState from'@/shared/components/WareState.vue';import{accessControlApi,type Role,type PermissionGroup,type Permission}from'../../api/access-control.api'
type Node=Permission&{children:Node[]};const tab=ref<'roles'|'groups'>('roles'),loading=ref(true),error=ref(''),roles=ref<Role[]>([]),groups=ref<PermissionGroup[]>([]),permissions=ref<Permission[]>([]),roleEditor=ref<Role|null>(null),groupEditor=ref<any|null>(null),selected=ref<number[]>([]),saving=ref(false);
const tree=computed(()=>{const map=new Map<number,Node>();permissions.value.forEach(x=>map.set(x.id,{...x,children:[]}));const roots:Node[]=[];map.forEach(x=>{const parent=map.get(x.parent_id);parent?parent.children.push(x):roots.push(x)});return roots});const parseIds=(v:string|null)=>v?v.split(',').map(Number):[];
async function load(){loading.value=true;error.value='';try{[roles.value,groups.value,permissions.value]=await Promise.all([accessControlApi.roles(),accessControlApi.groups(),accessControlApi.permissions()])}catch(e){error.value=e instanceof Error?e.message:'权限配置加载失败'}finally{loading.value=false;uni.stopPullDownRefresh()}}
function editRole(r:Role){roleEditor.value=r;selected.value=parseIds(r.group_ids)}function editGroup(g?:PermissionGroup){groupEditor.value=g?{...g}:{id:0,code:'',name:'',description:'',status:1};selected.value=g?parseIds(g.permission_ids):[]}
function descendants(node:Node):number[]{return[node.id,...node.children.flatMap(descendants)]}function toggleNode(node:Node){const ids=descendants(node),all=ids.every(id=>selected.value.includes(id));selected.value=all?selected.value.filter(id=>!ids.includes(id)):[...new Set([...selected.value,...ids])]}
async function saveRole(){if(!roleEditor.value||saving.value)return;saving.value=true;try{await accessControlApi.saveRoleGroups(roleEditor.value.id,selected.value);roleEditor.value=null;uni.showToast({title:'角色权限已保存',icon:'success'});load()}finally{saving.value=false}}
async function saveGroup(){if(!groupEditor.value||saving.value)return;saving.value=true;try{await accessControlApi.saveGroup({...groupEditor.value,permissionIds:selected.value});groupEditor.value=null;uni.showToast({title:'权限组已保存',icon:'success'});load()}catch(e){uni.showToast({title:e instanceof Error?e.message:'保存失败',icon:'none'})}finally{saving.value=false}}
onShow(load);onPullDownRefresh(load)
</script>
<template><view class="page"><view class="segments"><view :class="{active:tab==='roles'}" @click="tab='roles'">角色管理</view><view :class="{active:tab==='groups'}" @click="tab='groups'">权限组管理</view></view><view v-if="tab==='groups'" class="actions"><text>权限组定义可复用的业务能力组合</text><button @click="editGroup()">新增权限组</button></view><WareState v-if="loading" type="loading" title="正在加载权限配置"/><WareState v-else-if="error" type="error" title="加载失败" :description="error" action-label="重试" @action="load"/><view v-else-if="tab==='roles'" class="list"><view v-for="r in roles" :key="r.id" class="item" @click="editRole(r)"><view><b>{{r.name}}</b><span>{{r.account_count}}个账户</span></view><text>{{r.description||'未填写说明'}}</text><small>{{parseIds(r.group_ids).length}}个权限组　点击配置 ›</small></view></view><view v-else class="list"><view v-for="g in groups" :key="g.id" class="item" @click="editGroup(g)"><view><b>{{g.name}}</b><span>{{g.role_count}}个角色</span></view><text>{{g.description||g.code}}</text><small>{{parseIds(g.permission_ids).length}}项权限　点击编辑 ›</small></view></view><view v-if="roleEditor||groupEditor" class="mask" @click="roleEditor=null;groupEditor=null"><view class="drawer" @click.stop><view class="handle"/><view class="drawer-head"><view><b>{{roleEditor?'配置角色权限组':groupEditor.id?'编辑权限组':'新增权限组'}}</b><small>{{roleEditor?.name||'按业务领域勾选权限'}}</small></view><text @click="roleEditor=null;groupEditor=null">关闭</text></view><template v-if="roleEditor"><view class="check-list"><view v-for="g in groups" :key="g.id" :class="['check-row',{checked:selected.includes(g.id)}]" @click="selected.includes(g.id)?selected=selected.filter(x=>x!==g.id):selected=[...selected,g.id]"><i>{{selected.includes(g.id)?'✓':''}}</i><view><b>{{g.name}}</b><small>{{g.description}}</small></view></view></view><button class="primary" @click="saveRole">保存角色权限</button></template><template v-else><view class="fields"><label v-if="!groupEditor.id">权限组编码<input v-model="groupEditor.code" placeholder="如 quality_operator"/></label><label>权限组名称<input v-model="groupEditor.name" placeholder="请输入名称"/></label><label>说明<input v-model="groupEditor.description" placeholder="说明适用人员和能力"/></label></view><view class="tree-title">关联领域权限 <text>已选{{selected.length}}项</text></view><scroll-view scroll-y class="tree"><view v-for="root in tree" :key="root.id" class="root"><view class="node level0" @click="toggleNode(root)"><i>{{selected.includes(root.id)?'✓':''}}</i><b>{{root.name}}</b><small>{{root.children.length}}项</small></view><template v-for="child in root.children" :key="child.id"><view class="node level1" @click="toggleNode(child)"><i>{{selected.includes(child.id)?'✓':''}}</i><b>{{child.name}}</b><small>{{child.children.length?child.children.length+'项':child.description}}</small></view><view v-for="leaf in child.children" :key="leaf.id" class="node level2" @click="toggleNode(leaf)"><i>{{selected.includes(leaf.id)?'✓':''}}</i><b>{{leaf.name}}</b></view></template></view></scroll-view><button class="primary" @click="saveGroup">保存权限组</button></template></view></view></view></template>
<style scoped>.page{min-height:100vh;padding:20rpx 22rpx;background:var(--wms-surface-page)}.segments{display:grid;grid-template-columns:1fr 1fr;padding:5rpx;border:1rpx solid var(--wms-border);border-radius:11rpx;background:#fff}.segments view{height:62rpx;line-height:62rpx;text-align:center;font-size:23rpx}.segments .active{border-radius:8rpx;background:var(--wms-primary-700);color:#fff;font-weight:700}.actions{display:flex;align-items:center;justify-content:space-between;margin-top:16rpx}.actions text{color:var(--wms-text-secondary);font-size:19rpx}.actions button{height:58rpx;margin:0;padding:0 18rpx;border-radius:9rpx;background:var(--wms-primary-700);color:#fff;font-size:20rpx;line-height:58rpx}.list{display:flex;flex-direction:column;gap:12rpx;margin-top:17rpx}.item{padding:19rpx 20rpx;border:1rpx solid var(--wms-border);border-radius:12rpx;background:#fff}.item>view{display:flex;align-items:center;justify-content:space-between}.item b{font-size:25rpx}.item span{color:var(--wms-primary-700);font-size:19rpx}.item text,.item small{display:block;margin-top:8rpx}.item text{font-size:20rpx}.item small{color:var(--wms-text-secondary);font-size:18rpx}.mask{position:fixed;z-index:50;inset:0;display:flex;align-items:flex-end;background:rgba(20,38,36,.45)}.drawer{box-sizing:border-box;width:100%;max-height:92vh;padding:15rpx 24rpx calc(24rpx + env(safe-area-inset-bottom));border-radius:28rpx 28rpx 0 0;background:#fff}.handle{width:68rpx;height:7rpx;margin:0 auto 18rpx;border-radius:8rpx;background:var(--wms-border)}.drawer-head{display:flex;align-items:flex-start;justify-content:space-between}.drawer-head b,.drawer-head small{display:block}.drawer-head b{font-size:28rpx}.drawer-head small{margin-top:5rpx;color:var(--wms-text-secondary);font-size:19rpx}.drawer-head>text{color:var(--wms-primary-700);font-size:21rpx}.check-list{max-height:58vh;margin-top:18rpx;overflow:auto}.check-row,.node{display:flex;align-items:center;border-bottom:1rpx solid var(--wms-border)}.check-row{min-height:82rpx}.check-row i,.node i{display:flex;width:30rpx;height:30rpx;align-items:center;justify-content:center;margin-right:15rpx;border:1rpx solid var(--wms-border);border-radius:5rpx;color:#fff;font-size:19rpx;font-style:normal}.check-row.checked i,.node i:not(:empty){border-color:var(--wms-primary-700);background:var(--wms-primary-700)}.check-row b,.check-row small{display:block}.check-row b{font-size:22rpx}.check-row small{margin-top:4rpx;color:var(--wms-text-secondary);font-size:17rpx}.fields label{display:block;margin-top:14rpx;font-size:20rpx}.fields input{height:62rpx;margin-top:7rpx;padding:0 14rpx;border:1rpx solid var(--wms-border);border-radius:9rpx;font-size:21rpx}.tree-title{display:flex;justify-content:space-between;margin:20rpx 0 8rpx;font-size:23rpx;font-weight:700}.tree-title text{color:var(--wms-primary-700);font-size:19rpx}.tree{height:48vh;border-top:1rpx solid var(--wms-border)}.node{min-height:65rpx}.node b{font-size:21rpx}.node small{margin-left:auto;color:var(--wms-text-secondary);font-size:17rpx}.level0{background:var(--wms-surface-soft);font-weight:700}.level1{padding-left:28rpx}.level2{padding-left:67rpx}.primary{height:72rpx;margin-top:16rpx;border-radius:10rpx;background:var(--wms-primary-700);color:#fff;font-size:24rpx;line-height:72rpx}</style>
